-- ============================================================
-- Full data import from Supabase cloud -> local PostgreSQL
-- Generated 2026-11-14. Run as the postgres superuser:
--   psql -U postgres -d restopos -f tools/local_import_data.sql
-- Safe to re-run (ON CONFLICT DO NOTHING everywhere).
-- ============================================================
\set ON_ERROR_STOP on
BEGIN;
SET session_replication_role = replica;

-- ---- clear the sample/demo data that local_setup.sql seeded ----
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' LOOP
    EXECUTE format('TRUNCATE TABLE public.%I CASCADE', r.table_name);
  END LOOP;
END $$;
DELETE FROM auth.users;

-- ---- auth.users (cloud domain -> @store.local) ----
ON CONFLICT (id) DO UPDATE SET email=EXCLUDED.email, encrypted_password=EXCLUDED.encrypted_password;
-- Local admin keeps the simple password used on this PC
UPDATE auth.users SET encrypted_password = crypt('1234', gen_salt('bf')) WHERE email='admin@store.local';

-- ---- public data ----
SELECT setval(pg_get_serial_sequence('public.audit_log','id'), (SELECT coalesce(max(id),1) FROM public.audit_log));
SET session_replication_role = DEFAULT;
COMMIT;
\echo 'IMPORT COMPLETE'
